/**
 * LiDAR demo catalogue. Both datasets are SYNTHETIC benchmarks generated by the GeoVision 3D reference project
 * with mathematically known geometry. They are not real surveys. Their value is that every measurement the
 * viewer makes can be checked against an exact answer.
 */
export interface LidarDataset {
  id: string;
  name: string;
  category: string;
  summary: string;
  description: string;
  application: string;
  files: { role: 'single' | 'pre' | 'post'; url: string; label: string }[];
  groundTruthUrl: string;
  inputFormat: string;
  outputFormat: string;
  previewUrl: string;
  kind: 'terrain' | 'change';
  licence: string;
  source: string;
  labels: string[];
}

export const LIDAR_DATASETS: LidarDataset[] = [
  {
    id: 'lidar-terrain-benchmark',
    name: 'Synthetic LiDAR Terrain Benchmark',
    category: 'LiDAR Point Cloud · Terrain & Structure',
    summary: 'Flat ground, a Gaussian hill and a 10 × 10 × 5 m structure, with known ground truth to check every measurement.',
    description:
      'A synthetic classified LiDAR point cloud (LAS 1.2, point format 3, colour). It contains a flat ground plane at Z = 10 m, a Gaussian hill peaking at Z = 30 m and a box-shaped structure labelled as building (ASPRS class 6). ' +
      'Because the geometry is defined by equations, distance, height, area and volume results can be compared with exact expected values.',
    application: 'Validating point-cloud measurement, volume and elevation tools before using them on real LiDAR surveys.',
    files: [{ role: 'single', url: '/lidar/synthetic_terrain.las', label: 'synthetic_terrain.las' }],
    groundTruthUrl: '/lidar/synthetic_ground_truth.json',
    inputFormat: 'LAS 1.2 point cloud (synthetic)',
    outputFormat: 'Interactive point cloud (no mesh)',
    previewUrl: '/lidar/terrain-preview.jpg',
    kind: 'terrain',
    licence: 'CC0 1.0 (stated for this file in the reference project)',
    source: 'GeoVision 3D reference project, sample-data/synthetic_terrain.las (generated by generate_synthetic_las.py)',
    labels: ['Demo Project', 'Synthetic Dataset', 'LiDAR'],
  },
  {
    id: 'lidar-landslide-change',
    name: 'Synthetic Landslide Change Detection',
    category: 'LiDAR Point Cloud · Change Detection',
    summary: 'Pre- and post-event terrain with a known excavation and deposit, for volume-of-change checks.',
    description:
      'Two synthetic LiDAR epochs of the same 100 × 100 m slope: before and after an excavation (scarp) with material deposited below it (toe). ' +
      'The viewer builds a surface model of each epoch and computes the volume lost and gained from the difference, then shows it next to the analytical values from the generator.',
    application: 'Landslide, stockpile and earthworks monitoring: comparing two surveys to quantify material moved.',
    files: [
      { role: 'pre', url: '/lidar/synthetic_landslide_pre.las', label: 'synthetic_landslide_pre.las' },
      { role: 'post', url: '/lidar/synthetic_landslide_post.las', label: 'synthetic_landslide_post.las' },
    ],
    groundTruthUrl: '/lidar/synthetic_landslide_ground_truth.json',
    inputFormat: 'Two LAS 1.2 point clouds (synthetic)',
    outputFormat: 'Interactive point cloud + elevation-change colouring',
    previewUrl: '/lidar/landslide-preview.jpg',
    kind: 'change',
    licence: 'No licence stated in the reference project for this pair (generated by the same project as the terrain file). Confirm with its author before public release.',
    source: 'GeoVision 3D reference project, sample-data/synthetic_landslide_{pre,post}.las (generated by generate_synthetic_landslide.py)',
    labels: ['Demo Project', 'Synthetic Dataset', 'LiDAR'],
  },
];

export const getLidarDataset = (id?: string) => LIDAR_DATASETS.find(d => d.id === id);
